const cmd = $fromAI('command', 'The command to execute', 'string');
const { execSync } = require('child_process');
try {
  const output = execSync(cmd, { timeout: 30000, encoding: 'utf8', maxBuffer: 1024 * 1024 });
  return output.trim() || '(command completed with no output)';
} catch (err) {
  return `Error: ${err.message}\nStderr: ${err.stderr || ''}`.trim();
}

const filePath = $fromAI('path', 'Full path to the file to read', 'string');
const fs = require('fs');
try {
  const content = fs.readFileSync(filePath, 'utf8');
  return content.slice(0, 8000);
} catch (err) {
  return `Error reading file: ${err.message}`;
}

const filePath = $fromAI('path', 'Full path to write the file to', 'string');
const content = $fromAI('content', 'The content to write to the file', 'string');
const fs = require('fs');
const path = require('path');
try {
  const dir = path.dirname(filePath);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(filePath, content, 'utf8');
  return `File written successfully: ${filePath} (${content.length} characters)`;
} catch (err) {
  return `Error writing file: ${err.message}`;
}

const dirPath = $fromAI('path', 'Directory path to list', 'string');
const fs = require('fs');
const path = require('path');
try {
  const entries = fs.readdirSync(dirPath, { withFileTypes: true });
  const result = entries.slice(0, 50).map(e => {
    const icon = e.isDirectory() ? '[DIR]' : '[FILE]';
    let size = '';
    if (!e.isDirectory()) {
      try { const s = fs.statSync(path.join(dirPath, e.name)); size = ` (${(s.size / 1024).toFixed(1)} KB)`; } catch {}
    }
    return `${icon} ${e.name}${size}`;
  });
  return `Contents of ${dirPath}:\n${result.join('\n')}`;
} catch (err) {
  return `Error: ${err.message}`;
}
